function EvaluateHttpPluginPayLoad(response) local label = response.deployment_label or 'copilot-bicep-debug' local content = [[targetScope = 'subscription'
param location string = 'eastus'
resource rg 'Microsoft.Resources/resourceGroups@2024-03-01' = {
  name: 'rg-copilot-bicep-debug'
  location: location
}
]] return { bicep_config = { artifactId = 'bicep-op_debug', name = label, parts = { { kind = 'data', data = { files = { { file_name = 'main.bicep', content = content } } } } }, metadata = { type = 'bicep' } }, subscription_id = response.subscription_id, location = response.location or 'eastus', async_response = true, messageLocale = 'en-US' } end
